import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';

// Apne components ko yahan import karein
import BookingForm from '../components/booking/BookingForm';
import TrackingSection from '../components/tracking/TrackingSection';

// Agar aapne Home page banaya hai toh use yahan import karein
// import Home from '../components/Home/Home';

const AppRoutes = () => {
    return (
        <Routes>
            {/* 1. Default Route: Jab koi website open kare (localhost:3000) */}
            {/* Abhi ke liye hum ise BookingForm par redirect kar rahe hain */}
            <Route path="/" element={<Navigate to="/book" />} />

            {/* 2. Booking Route: localhost:3000/book */}
            <Route path="/book" element={<BookingForm />} />

            {/* 3. Tracking Route: localhost:3000/track */}
            <Route path="/track" element={<TrackingSection />} />

            {/* 4. Admin Route (Optional): Future mein Admin Panel ke liye */}
            <Route path="/admin" element={<div style={{padding: '50px', textAlign: 'center'}}><h2>Admin Panel Coming Soon...</h2></div>} />

            {/* 5. 404 Route: Agar user galat URL daale */}
            <Route path="*" element={<div style={{padding: '50px', textAlign: 'center'}}><h2>404 - Page Not Found</h2></div>} />
        </Routes>
    );
};

export default AppRoutes;
